<?php
namespace App\Services\ProfileUpdates;
use App\Models\{Club,Member,ProfileUpdateRequest};
class ProfileUpdateReadService{
 public function list(Club $club,array $filters,?Member $own=null):array{$q=ProfileUpdateRequest::with(['member','changes'])->where('club_id',$club->id)->when($own,fn($x)=>$x->where('member_id',$own->id));foreach(['status'] as $f)if(isset($filters[$f]))$q->where($f,$filters[$f]);if(isset($filters['member_search']))$q->whereHas('member',fn($m)=>$m->where('full_name','like','%'.trim($filters['member_search']).'%')->orWhere('member_code','like','%'.trim($filters['member_search']).'%'));if(isset($filters['changed_field']))$q->whereHas('changes',fn($c)=>$c->where('field_key',$filters['changed_field']));if(isset($filters['date_from']))$q->whereDate('submitted_at','>=',$filters['date_from']);if(isset($filters['date_to']))$q->whereDate('submitted_at','<=',$filters['date_to']);$p=$q->orderByDesc('submitted_at')->orderByDesc('id')->paginate($filters['per_page']??25,['*'],'page',$filters['page']??1);return ['data'=>collect($p->items())->map(fn($r)=>$this->summary($r))->all(),'meta'=>['current_page'=>$p->currentPage(),'last_page'=>$p->lastPage(),'per_page'=>$p->perPage(),'total'=>$p->total()]];}
 public function detail(Club $club,ProfileUpdateRequest $r,?Member $own=null):array{abort_if($r->club_id!==$club->id||($own&&$r->member_id!==$own->id),404);$r->load(['member','requester','reviewer','changes']);return ['data'=>[...$this->summary($r),'requester_id'=>$r->requester_user_id,'reviewer_name'=>$r->reviewer?->name,'rejection_reason'=>$r->rejection_reason,'lock_version'=>$r->lock_version,'source_member_updated_at'=>$r->source_member_updated_at?->toISOString(),'source_fingerprint'=>$r->source_fingerprint,'changes'=>$r->changes->sortBy('field_key')->values()->map(fn($c)=>['id'=>$c->id,'field_key'=>$c->field_key,'classification'=>$c->classification,'original_value'=>$c->original_value,'proposed_value'=>$c->proposed_value])->all()]];}
 private function summary(ProfileUpdateRequest $r):array{return ['id'=>$r->id,'member'=>['id'=>$r->member->id,'member_code'=>$r->member->member_code,'display_name'=>$r->member->full_name],'status'=>$r->status,'submitted_at'=>$r->submitted_at->toISOString(),'decided_at'=>$r->decided_at?->toISOString(),'changed_fields'=>$r->changes->pluck('field_key')->sort()->values()->all()];}}
